CREATE TABLE products(tenant text NOT NULL,id text NOT NULL,name text NOT NULL,price_cents bigint NOT NULL CHECK(price_cents>0),stock integer NOT NULL CHECK(stock>=0),PRIMARY KEY(tenant,id));
CREATE TABLE orders(tenant text NOT NULL,id text NOT NULL,owner_id text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','paid','cancelled','expired')),total_cents bigint NOT NULL CHECK(total_cents>0),expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes',created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant,id));
CREATE TABLE order_items(tenant text NOT NULL,order_id text NOT NULL,product_id text NOT NULL,quantity integer NOT NULL CHECK(quantity>0),unit_price_cents bigint NOT NULL CHECK(unit_price_cents>0),PRIMARY KEY(tenant,order_id,product_id),FOREIGN KEY(tenant,order_id) REFERENCES orders(tenant,id),FOREIGN KEY(tenant,product_id) REFERENCES products(tenant,id));
CREATE TABLE payment_events(tenant text NOT NULL,event_id text NOT NULL,order_id text NOT NULL,outcome text NOT NULL CHECK(outcome IN ('success','failure')),PRIMARY KEY(tenant,event_id));
